mod = 998244353

def count_good_sequences(length, mod):
    if length == 1:
        return [1]
    if length == 2:
        return [3, 1]

    # Recurrence relation for the number of good sequences.
    # F(length) = F(length - 1) * length * (length - 1) % MOD
    def F(length):
        dp = [2] * length
        dp[0] = 1
        for i in range(1, length):
            dp[i] = dp[-1] * length % mod * (i - 1) % mod
        return sum(dp) % mod

    F1 = F(length)
    dp = [1, F1 - 1]
    for i in range(3, length + 1):
        dp.append(2 * dp[-1] * i % mod)
        dp.pop(0)

    return dp

def solve(length, mod):
    return count_good_sequences(length, mod)

n = int(input())
