from bisect import bisect_left, bisect_right
from math import ceil

def find_coat_length(coats):
    hooks = sorted(range(len(coats)), key=lambda i: (coats[i], i[::-1]))
    for i in range(len(coats)):
        for j in range(1, len(coats[i])):
            if coats[i][j] == coats[i][j-1]:
                sorted_hook = list(range(bisect_left(hooks, i), bisect_right(hooks, i)))
                for k in sorted_hook:
                    if coats[i][j] != coats[k]:
                        return sorted_hook[k - i + 1]
    return 1

