import math

def calculate_exlog_f(n, A, B, C, D, x):
    return (A*x**3 + B*x**2 + C*x + D) % (1<<32)

def main():
    n, A, B, C, D = map(int, input().split())
    result = 0
    mod = (1<<32)

    # The sum can be calculated by summing up the contributions of each number i from 2 to n
    # to L(x) = i(x)**3 + i(x)**2 + i(x) + 1 for each input input on itself.
    for i in range(2, n+1):
        result += calculate_exlog_f(i, A, B, C, D, i)

    print(result % mod)

