import collections

def build_tree(edges):
    graph = collections.defaultdict(list)
    for a, b in edges:
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)
    return graph

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)
        if current_distance > distances[current_node]:
            continue
        for neighbor in graph[current_node]:
            distance = current_distance + graph[current_node][neighbor]
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))
    return distances

def query_cost(graph, distances, destination):
    dists = [float('inf')]*len(graph)
    for node in graph:
        dists[node] = distances[node]
        distances[node][0] = 0
    dists[0][0] = 0

    for _ in range(len(graph)-1):
        for n in graph:
            for nei in graph[n]:
                if n in graph and nei in graph:
                    for i in range(1, len(graph[n])):
                        dists[n][i] = min(dists[n][i], dists[nei][i-1])
    return dists[destination][len(graph)-1]

