import sys

def find_max_final_element(N, nums):
    if N == 2:
        return max(nums[0], nums[1]), 1
    elif N == 3:
        max_num = max(nums)
        ops = 0
        if max_num == max(nums):
            return 1, 3
        else:
            return 2, 2

    n = N - 2  # Number of internal elements
    ops = counter = left = right = 0

    while len(nums) > 1:
        max_num = max(nums)
        if max_num in nums[:n+1]:
            index = nums.index(max_num)
            if index == 0:
                nums = nums[:index] + nums[index+1:]
            elif index == len(nums) - 1:
                nums = nums[:index] + nums[index+1:]
            else:
                prev = nums[index-1]
                next_ = nums[index+1]
                if prev < next_:
                    nums[index] = next_
                    nums = nums[:index] + nums[index+1:]
                else:
                    nums[index] = next_
                    nums = nums[:index] + nums[index+1:]
        index = nums.index(max_num)
        if index > 0:
            left = max(nums[:index])
            if left > max([nums[index-1], index-1]):
                counter -= 1
                nums.pop(index-len(nums))
            else:
                counter += 1
                left = min(nums)
                nums = [max(nums)] + nums[0:index-1] + [min(nums)] + nums[index+1:]
        elif right == nums[-1]:
            counter += 1
            nums = nums[:-1] + nums[index+1:]
        else:
            right = min(nums[index])
            if index < n:
                if nums[index] > max(nums[index-1], index-1):
                    counter += 1
                    left = min(nums)
                    nums = [max(nums)] + nums[0:index] + [min(nums)] + nums[index+1:]
                else:
                    counter -= 1
                    nums.pop(index)
            if max(nums) < right or right < min(nums[index+1:]):
                counter -= 1
                nums.remove(right)
                if len(nums) > 1:
                    nums = nums[:index] + nums[right+1:]
                else:
                    break

        ops += counter

    return max(nums), ops

