from collections import defaultdict

def process_sequence(sequence):
    n = len(sequence)
    graph = defaultdict(dict)
    for i, num in enumerate(sequence):
        graph[0][i] = num
        graph[num][i] = []

    for i in range(1, 9):  # pool range
        for u in range(n):
            for v in range(u + 1, n):
                if sequence[u] + u * i >= sequence[v] and sequence[v] + v * i in sequence:
                    if u not in graph[sequence[u] + u * i]:
                        graph[sequence[u] + u * i].update({u: 1, v: 1})
                    else:
                        graph[sequence[u] + u * i][u] += 1
                        graph[sequence[u] + u * i][v] += 1

    return graph

def get_beauty(graph, start):
    nodes = set([i for i in range(1, 9)])
    visited = set([1, 6])
    queue = [(start, 0)]

    while queue:
        u, size = queue.pop()
        if u in visited:
            visited.remove(u)
            continue
        if u in nodes and size + 1 <= len(graph[u]):
            visited.add(u)
        if u in graph:
            for neighbor in graph[u]:
                if neighbor in visited:
                    continue
                queue.append((neighbor, size - graph[u][neighbor] + 1))

    return len(visited) if len(visited) <= 3 else 3

def query_beauty(bigram, graph):
    beauty = 0
    for a, b in bigram:
        beauty += get_beauty(graph, a)
    return beauty

