from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    rootx = find(parent, x)
    rooty = find(parent, y)
    if rootx != rooty:
        if rank[rootx] < rank[rooty]:
            parent[rootx] = rooty
        elif rank[rootx] > rank[rooty]:
            parent[rooty] = rootx
        else:
            parent[rooty] = rootx
            rank[rootx] += 1

def is_special_case(parent, types, u, v):
    if u == v:
        return False
    if types[u - 1] != 0:
        return True
    rootu = find(parent, u)
    rootv = find(parent, v)
    while rootu != rootv:
        rootu = find(parent, rootu)
        rootv = find(parent, rootv)
    return rootu == find(parent, v)

def is_part(parent, types, u, v):
    if u == v:
        return True
    if types[u - 1] == 1:
        return False
    rootu = find(parent, u)
    rootv = find(parent, v)
    while rootu != rootv:
        if rootu in parent:
            rootu = find(parent, rootu)
        if rootv in parent:
            rootv = find(parent, rootv)
