from collections import deque

def recover_array(b_prime, c_prime):
    n = len(b_prime)
    queue = deque(range(1, n + 1))
    for i, b_prime_i in enumerate(b_prime):
        new_len = len(queue)
        if i == new_len:
            return [-1]
        elif i == 0:
            measured = c_prime[i]
            for j in range(1, new_len):
                if queue[j] < measured:
                    queue.appendleft(queue.pop(j))
            if queue[new_len - 1] < measured:
                queue.appendleft(queue.pop(new_len - 1))
        else:
            measured = queue[0]
            measure_mod = c_prime[i] % measured
            indexes_to_remove = 0
            for j in range(new_len):
                if queue[j] < measured - measure_mod:
                    queue.remove(queue[j])
                    indexes_to_remove += 1
                if i + indexes_to_remove < new_len:
                    new_measure = queue[0] * measure_mod + queue[i + indexes_to_remove]
                    if new_measure % measured == measured - measure_mod:
                        queue.remove(queue[0])
                        queue.remove(queue[i + indexes_to_remove])
                else:
                    break
    a = []
    for i in range(n):
        a.append(queue[i])
    return a

