from math import factorial

def dp(array, m, n):
    dp = [[0 for _ in range(n+1)] for _ in range(m+1)]
    for x in range(n+1):
        dp[0][x] = 1
    for i in range(1, m+1):
        for length in range(i, i+2):
            for h in range(n-length+1):
                dp[i][length+h] = dp[i-1][length+h]
            for l in range(length):
                dp[i][length+h] -= dp[i][l] * factorial(n-length+l) / (factorial(l) * factorial(n-length)-factorial(l+1) * factorial(n-length-l))
    return dp[-1][-1] * 1.0 / factorial(n)

