            return 'YES', a, b
    return 'NO', [[], []]

n = int(input().strip())
memories = [list(map(int, input().strip().split())) for _ in range(n)]

unique_solution_flag, a, b = restore_order(*zip(*memories))

if unique_solution_flag == 'YES':
    print('YES')
    for i in a:
        print(i, end=' ')
    print()
else:
    print('NO\nNO\nYES\n')
    for ps in sample(memories, 2):
        print(*ps[0])
        print(*ps[1])
